script:
frappe.ui.form.on('Revaluation Application', {
  refresh: function(frm) {
    frm.trigger('calculate_total_fee');
  },
  items_add: function(frm) {
    frm.trigger('calculate_total_fee');
  },
  items_remove: function(frm) {
    frm.trigger('calculate_total_fee');
  },
  calculate_total_fee: function(frm) {
    let total = 0;
    (frm.doc.items || []).forEach(function(row) {
      total += row.fee_amount || 0;
    });
    frm.set_value('total_fee', total);
  }
});

frappe.ui.form.on('Feedback Survey', {
  refresh: function(frm) {
    frm.set_df_property('questions', 'cannot_add_rows', frm.doc.status === 'Open');
  },
  status: function(frm) {
    if (frm.doc.status === 'Open') {
      frm.set_df_property('questions', 'cannot_add_rows', 1);
      frm.set_df_property('questions', 'cannot_delete_rows', 1);
    }
  }
});

frappe.ui.form.on('Assignment', {
  validate: function(frm) {
    if (frm.doc.due_date && frm.doc.creation) {
      let created = frappe.datetime.str_to_obj(frm.doc.creation);
      let due = frappe.datetime.str_to_obj(frm.doc.due_date);
      if (due < created) {
        frappe.throw(__('Due date cannot be earlier than the creation date'));
      }
    }
  }
});

frappe.ui.form.on('Library Member', {
  validate: function(frm) {
    if (frm.doc.phone && !/^[0-9]{10}$/.test(frm.doc.phone)) {
      frappe.throw(__('Phone number must be 10 digits'));
    }
    if (frm.doc.email && !/@/.test(frm.doc.email)) {
      frappe.throw(__('Please enter a valid email address'));
    }
  }
});

frappe.ui.form.on('Hostel Room', {
  validate: function(frm) {
    if (frm.doc.current_occupancy > frm.doc.capacity) {
      frappe.throw(__('Current occupancy (' + frm.doc.current_occupancy + ') cannot exceed capacity (' + frm.doc.capacity + ')'));
    }
  }
});

frappe.ui.form.on('Transport Allocation', {
  validate: function(frm) {
    if (frm.doc.to_date && frm.doc.from_date && frm.doc.to_date < frm.doc.from_date) {
      frappe.throw(__('To Date cannot be before From Date'));
    }
  }
});

frappe.ui.form.on('Grievance', {
  refresh: function(frm) {
    if (frm.doc.urgency === 'Critical' && frm.doc.status !== 'Resolved') {
      frm.set_intro(__('This is a CRITICAL grievance requiring immediate attention!'), 'red');
    }
  }
});

frappe.ui.form.on('Student Certificate Request', {
  student: function(frm) {
    if (frm.doc.student) {
      frappe.call({
        method: 'frappe.client.get',
        args: { doctype: 'Admission Student', name: frm.doc.student },
        callback: function(r) {
          if (r.message) {
            frm.set_value('student_name', r.message.student_name);
          }
        }
      });
    }
  }
});

frappe.ui.form.on('Convocation Registration', {
  refresh: function(frm) {
    if (frm.doc.docstatus === 1 && !frm.doc.attended) {
      frm.add_custom_button(__('Mark Attended'), function() {
        frm.set_value('attended', 1);
        frm.save();
      });
    }
  }
});

frappe.ui.form.on('OMR Answer Key', {
  validate: function(frm) {
    if (frm.doc.correct_answers) {
      let parts = frm.doc.correct_answers.split(',');
      if (parts.length !== frm.doc.total_questions) {
        frappe.msgprint(__('Warning: Number of answers (' + parts.length + ') does not match total questions (' + frm.doc.total_questions + ')'));
      }
    }
  }
});
